SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS helpdesk360_test CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE helpdesk360_test;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_logs; DROP TABLE IF EXISTS settings; DROP TABLE IF EXISTS user_scopes; DROP TABLE IF EXISTS user_assignments; DROP TABLE IF EXISTS positions; DROP TABLE IF EXISTS areas; DROP TABLE IF EXISTS parks; DROP TABLE IF EXISTS regions; DROP TABLE IF EXISTS support_team_members; DROP TABLE IF EXISTS support_teams; DROP TABLE IF EXISTS persistent_sessions; DROP TABLE IF EXISTS otp_requests; DROP TABLE IF EXISTS user_permissions; DROP TABLE IF EXISTS role_permissions; DROP TABLE IF EXISTS user_role_history; DROP TABLE IF EXISTS users; DROP TABLE IF EXISTS permissions; DROP TABLE IF EXISTS roles;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE roles(id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,description VARCHAR(255),sort_order SMALLINT NOT NULL DEFAULT 100,system_role TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB;
CREATE TABLE permissions(id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,module_name VARCHAR(80) NOT NULL,description VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_permissions_module(module_name))ENGINE=InnoDB;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,phone VARCHAR(30),role_id SMALLINT UNSIGNED NOT NULL,account_status ENUM('PENDING_ASSIGNMENT','ACTIVE','SUSPENDED','INACTIVE') NOT NULL DEFAULT 'PENDING_ASSIGNMENT',active TINYINT(1) NOT NULL DEFAULT 1,is_demo TINYINT(1) NOT NULL DEFAULT 0,registered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,verified_at DATETIME,last_login_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME,CONSTRAINT fk_users_role FOREIGN KEY(role_id) REFERENCES roles(id),INDEX idx_users_status(role_id,account_status,active),INDEX idx_users_name(name),INDEX idx_users_deleted(deleted_at))ENGINE=InnoDB;
CREATE TABLE user_role_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,role_id SMALLINT UNSIGNED NOT NULL,started_at DATETIME NOT NULL,ended_at DATETIME,reason VARCHAR(500) NOT NULL,changed_by BIGINT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_urh_user FOREIGN KEY(user_id) REFERENCES users(id),CONSTRAINT fk_urh_role FOREIGN KEY(role_id) REFERENCES roles(id),CONSTRAINT fk_urh_changed FOREIGN KEY(changed_by) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_urh_period(user_id,started_at,ended_at))ENGINE=InnoDB;
CREATE TABLE role_permissions(role_id SMALLINT UNSIGNED NOT NULL,permission_id SMALLINT UNSIGNED NOT NULL,allowed TINYINT(1) NOT NULL DEFAULT 1,PRIMARY KEY(role_id,permission_id),CONSTRAINT fk_rp_role FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,CONSTRAINT fk_rp_perm FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE user_permissions(user_id BIGINT UNSIGNED NOT NULL,permission_id SMALLINT UNSIGNED NOT NULL,allowed TINYINT(1) NOT NULL,PRIMARY KEY(user_id,permission_id),CONSTRAINT fk_up_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_up_perm FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE otp_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,email VARCHAR(190) NOT NULL,code_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,max_attempts TINYINT UNSIGNED NOT NULL DEFAULT 5,blocked_until DATETIME,requested_ip VARCHAR(45) NOT NULL,user_agent VARCHAR(500),consumed_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_otp_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_otp_email_created(email,created_at),INDEX idx_otp_ip_created(requested_ip,created_at),INDEX idx_otp_active(email,consumed_at,expires_at))ENGINE=InnoDB;
CREATE TABLE persistent_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,selector CHAR(32) NOT NULL UNIQUE,validator_hash CHAR(64) NOT NULL,device_name VARCHAR(160),user_agent VARCHAR(500),ip_address VARCHAR(45),last_ip_address VARCHAR(45),last_seen_at DATETIME NOT NULL,expires_at DATETIME NOT NULL,revoked_at DATETIME,revoke_reason VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_ps_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_ps_active(user_id,revoked_at,expires_at))ENGINE=InnoDB;
CREATE TABLE support_teams(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,description VARCHAR(255),active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)ENGINE=InnoDB;
CREATE TABLE support_team_members(team_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,is_lead TINYINT(1) NOT NULL DEFAULT 0,started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ended_at DATETIME,PRIMARY KEY(team_id,user_id,started_at),CONSTRAINT fk_stm_team FOREIGN KEY(team_id) REFERENCES support_teams(id),CONSTRAINT fk_stm_user FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_stm_active(user_id,ended_at))ENGINE=InnoDB;
CREATE TABLE regions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME)ENGINE=InnoDB;
CREATE TABLE parks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,region_id BIGINT UNSIGNED,name VARCHAR(160) NOT NULL UNIQUE,code VARCHAR(50) UNIQUE,address VARCHAR(300),active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME,CONSTRAINT fk_parks_region FOREIGN KEY(region_id) REFERENCES regions(id) ON DELETE SET NULL,INDEX idx_parks_region(region_id,active))ENGINE=InnoDB;
CREATE TABLE areas(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME)ENGINE=InnoDB;
CREATE TABLE positions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME)ENGINE=InnoDB;
CREATE TABLE user_assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,region_id BIGINT UNSIGNED,park_id BIGINT UNSIGNED,area_id BIGINT UNSIGNED,position_id BIGINT UNSIGNED,assignment_type ENUM('PARK','CORPORATE','OTHER') NOT NULL,started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ended_at DATETIME,created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_ua_user FOREIGN KEY(user_id) REFERENCES users(id),CONSTRAINT fk_ua_region FOREIGN KEY(region_id) REFERENCES regions(id) ON DELETE SET NULL,CONSTRAINT fk_ua_park FOREIGN KEY(park_id) REFERENCES parks(id) ON DELETE SET NULL,CONSTRAINT fk_ua_area FOREIGN KEY(area_id) REFERENCES areas(id) ON DELETE SET NULL,CONSTRAINT fk_ua_pos FOREIGN KEY(position_id) REFERENCES positions(id) ON DELETE SET NULL,CONSTRAINT fk_ua_creator FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_ua_user_active(user_id,ended_at),INDEX idx_ua_org(region_id,park_id,area_id,ended_at))ENGINE=InnoDB;
CREATE TABLE user_scopes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,scope_type ENUM('GLOBAL','REGION','PARK','AREA','TEAM') NOT NULL,region_id BIGINT UNSIGNED,park_id BIGINT UNSIGNED,area_id BIGINT UNSIGNED,team_id BIGINT UNSIGNED,started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ended_at DATETIME,reason VARCHAR(500),created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_us_user FOREIGN KEY(user_id) REFERENCES users(id),CONSTRAINT fk_us_region FOREIGN KEY(region_id) REFERENCES regions(id) ON DELETE SET NULL,CONSTRAINT fk_us_park FOREIGN KEY(park_id) REFERENCES parks(id) ON DELETE SET NULL,CONSTRAINT fk_us_area FOREIGN KEY(area_id) REFERENCES areas(id) ON DELETE SET NULL,CONSTRAINT fk_us_team FOREIGN KEY(team_id) REFERENCES support_teams(id) ON DELETE SET NULL,CONSTRAINT fk_us_creator FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_us_active(user_id,scope_type,ended_at))ENGINE=InnoDB;
CREATE TABLE settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(120) NOT NULL UNIQUE,setting_value TEXT,value_type ENUM('string','int','bool') NOT NULL DEFAULT 'string',description VARCHAR(255),updated_by BIGINT UNSIGNED,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_settings_user FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL)ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,persistent_session_id BIGINT UNSIGNED,module_name VARCHAR(80) NOT NULL,event_type VARCHAR(100) NOT NULL,entity_type VARCHAR(80),entity_id VARCHAR(80),old_values JSON,new_values JSON,metadata JSON,ip_address VARCHAR(45),device VARCHAR(80),user_agent VARCHAR(500),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_audit_session FOREIGN KEY(persistent_session_id) REFERENCES persistent_sessions(id) ON DELETE SET NULL,INDEX idx_audit_user_date(user_id,created_at),INDEX idx_audit_event(event_type,created_at),INDEX idx_audit_entity(entity_type,entity_id,created_at))ENGINE=InnoDB;
INSERT INTO roles(code,name,description,sort_order) VALUES ('SOLICITANTE','Solicitante','Crea y consulta sus propios casos',10),('TECNICO','Técnico','Gestiona casos dentro de su autorización',20),('SUPERVISOR_IT','Supervisor IT','Supervisión operativa del Helpdesk',30),('GERENCIA','Gerencia / Consulta','Consulta gerencial y reportes',40),('ADMINISTRADOR','Administrador','Administración completa del sistema',50);
INSERT INTO permissions(code,name,module_name) VALUES
('tickets.create','Crear tickets','Tickets'),('tickets.view.self','Ver tickets propios','Tickets'),('tickets.view.assigned','Ver tickets asignados','Tickets'),('tickets.view.scope','Ver tickets por alcance','Tickets'),('tickets.view.all','Ver todos los tickets','Tickets'),('tickets.assign','Asignar tickets','Tickets'),('tickets.reassign','Reasignar tickets','Tickets'),('tickets.change_status','Cambiar estado','Tickets'),('tickets.resolve','Resolver ticket','Tickets'),('tickets.close','Cerrar ticket','Tickets'),('tickets.reopen','Reabrir ticket','Tickets'),('tickets.comment','Responder públicamente','Tickets'),('tickets.internal_comment','Crear nota interna','Tickets'),('reports.view','Ver informes','Reportes'),('reports.export','Exportar informes','Reportes'),('knowledge.view','Consultar soluciones e historial','Conocimiento'),('knowledge.manage','Administrar soluciones conocidas','Conocimiento'),('users.manage','Administrar usuarios','Administración'),('organization.manage','Administrar organización','Administración'),('roles.manage','Administrar roles','Administración'),('permissions.manage','Administrar permisos','Administración'),('audit.view','Ver auditoría','Administración'),('settings.manage','Administrar configuración','Administración');
INSERT INTO role_permissions(role_id,permission_id,allowed) SELECT r.id,p.id,1 FROM roles r JOIN permissions p WHERE r.code='SOLICITANTE' AND p.code IN('tickets.create','tickets.view.self');
INSERT INTO role_permissions(role_id,permission_id,allowed) SELECT r.id,p.id,1 FROM roles r JOIN permissions p WHERE r.code='TECNICO' AND p.code IN('tickets.create','tickets.view.self','tickets.view.assigned','tickets.view.scope','tickets.change_status','tickets.resolve','tickets.comment','tickets.internal_comment','reports.view','knowledge.view');
INSERT INTO role_permissions(role_id,permission_id,allowed) SELECT r.id,p.id,1 FROM roles r JOIN permissions p WHERE r.code='SUPERVISOR_IT' AND p.code IN('tickets.create','tickets.view.self','tickets.view.assigned','tickets.view.scope','tickets.assign','tickets.reassign','tickets.change_status','tickets.resolve','tickets.close','tickets.reopen','tickets.comment','tickets.internal_comment','reports.view','reports.export','knowledge.view','knowledge.manage');
INSERT INTO role_permissions(role_id,permission_id,allowed) SELECT r.id,p.id,1 FROM roles r JOIN permissions p WHERE r.code='GERENCIA' AND p.code IN('tickets.view.all','reports.view','reports.export','knowledge.view');
